        for j in range(W):
            if (i==0 or i==H-1 or j==0 or j==W-1) and grid[i][j]==0:
                outside[i][j]=True; dq.append((i,j))
    while dq:
        x,y=dq.popleft()
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            nx,ny=x+dx,y+dy
            if 0<=nx<H and 0<=ny<W and not outside[nx][ny] and grid[nx][ny]==0:
                outside[nx][ny]=True; dq.append((nx,ny))
    seen=[[False]*W for _ in range(H)]
    comps=[]
    for i in range(H):
        for j in range(W):
            if grid[i][j]!=0 and not seen[i][j]:
                col=grid[i][j]
                stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    x,y=stack.pop(); cells.append((x,y))
                    for dx in (-1,0,1):
                        for dy in (-1,0,1):
                            if dx==0 and dy==0: continue
                            nx,ny=x+dx,y+dy
                            if 0<=nx<H and 0<=ny<W and not seen[nx][ny] and grid[nx][ny]==col:
